-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW
-- [2 col(s)].
----------------------------------------------------------------------------------------
with base as (
    select COVERAGE_HKEY, RECORD_SOURCE, LOAD_DATETIME, HASHDIFF,
           md5(coalesce(to_varchar(COVERAGE_DESCRIPTION), '^^') || '||' || coalesce(to_varchar(COVERAGE_NAME), '^^') || '||' || coalesce(to_varchar(PERIL_COVERED), '^^') || '||') as payload_sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COVERAGE_DEFINITION
     where RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS_COVER_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER_RISK_COVER_PROPERTY_RULE_LIST_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW')
),
seq as (
    select *,
           lag(HASHDIFF) over (partition by COVERAGE_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_hashdiff,
           lag(payload_sig) over (partition by COVERAGE_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_payload_sig
      from base
)
select 'MAXIMUS' as project, 'SAT_COVERAGE_DEFINITION' as satellite,
       count(*) as versions,
       count_if(HASHDIFF = prev_hashdiff) as unchanged_reinserts,
       count_if(payload_sig = prev_payload_sig) as unchanged_payload_reinserts,
       array_slice(array_agg(iff(HASHDIFF = prev_hashdiff or payload_sig = prev_payload_sig, to_varchar(COVERAGE_HKEY, 'HEX'), null))
                   within group (order by COVERAGE_HKEY), 0, 3) as examples,
       iff(unchanged_reinserts = 0 and unchanged_payload_reinserts = 0, 'PASS', 'FAIL') as status
  from seq;



