-- 37. MAXIMUS — SAT_COVERAGE_SUBLIMIT_SCHEDULE   [Implemented]
-- Multi-active: a version is the whole member set loaded at one LOAD_DATETIME; two
-- consecutive identical sets = an unchanged group was re-inserted. standard satellite,
-- automate_dv.ma_sat; PK COVERAGE_HKEY, child key ACTIVE_SEQUENCE_NUMBER; 1
-- RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS_COVER_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [3 col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME
-- per member.
----------------------------------------------------------------------------------------
with grp as (  -- one signature per loaded group (key, RECORD_SOURCE, LOAD_DATETIME)
    select COVERAGE_HKEY, RECORD_SOURCE, LOAD_DATETIME,
           listagg(to_varchar(ACTIVE_SEQUENCE_NUMBER) || ':' || to_varchar(HASHDIFF, 'HEX'), ',')
               within group (order by ACTIVE_SEQUENCE_NUMBER, HASHDIFF) as sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COVERAGE_SUBLIMIT_SCHEDULE
     where RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS_COVER_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW')
     group by COVERAGE_HKEY, RECORD_SOURCE, LOAD_DATETIME
),
seq as (
    select *, lag(sig) over (partition by COVERAGE_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_sig from grp
)
select 'MAXIMUS' as project, 'SAT_COVERAGE_SUBLIMIT_SCHEDULE' as satellite,
       count(*) as versions, count_if(sig = prev_sig) as unchanged_reinserts,
       array_slice(array_agg(iff(sig = prev_sig, to_varchar(COVERAGE_HKEY, 'HEX'), null)) within group (order by COVERAGE_HKEY), 0, 3) as examples,
       iff(unchanged_reinserts = 0, 'PASS', 'FAIL') as status
  from seq;



