-- 124. MAXIMUS — SAT_AUG_CLAIM_PROVIDER_BILLING   [Implemented]
-- Multi-active: a version is the whole member set loaded at one LOAD_DATETIME; two
-- consecutive identical sets = an unchanged group was re-inserted. augmented satellite,
-- automate_dv.ma_sat; PK CLAIM_HKEY, child key BILL_NUMBER; 1 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [23 col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME
-- per member.
----------------------------------------------------------------------------------------
with grp as (  -- one signature per loaded group (key, RECORD_SOURCE, LOAD_DATETIME)
    select CLAIM_HKEY, RECORD_SOURCE, LOAD_DATETIME,
           listagg(to_varchar(BILL_NUMBER) || ':' || to_varchar(HASHDIFF, 'HEX'), ',')
               within group (order by BILL_NUMBER, HASHDIFF) as sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_CLAIM_PROVIDER_BILLING
     where RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW')
     group by CLAIM_HKEY, RECORD_SOURCE, LOAD_DATETIME
),
seq as (
    select *, lag(sig) over (partition by CLAIM_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_sig from grp
)
select 'MAXIMUS' as project, 'SAT_AUG_CLAIM_PROVIDER_BILLING' as satellite,
       count(*) as versions, count_if(sig = prev_sig) as unchanged_reinserts,
       array_slice(array_agg(iff(sig = prev_sig, to_varchar(CLAIM_HKEY, 'HEX'), null)) within group (order by CLAIM_HKEY), 0, 3) as examples,
       iff(unchanged_reinserts = 0, 'PASS', 'FAIL') as status
  from seq;



----------------------------------------------------------------------------------------
