-- 170. MAXIMUS — SAT_AUG_PARTY_IDENTIFICATION   [Implemented]
-- Multi-active: a version is the whole member set loaded at one LOAD_DATETIME; two
-- consecutive identical sets = an unchanged group was re-inserted. augmented satellite,
-- automate_dv.ma_sat; PK PARTY_HKEY, child key IDENTIFICATION_TYPE_CODE; 5 RECORD_SOURCE
-- group(s):
-- MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW [1
-- col(s)],
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [2 col(s)],
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [12 col(s)],
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [2 col(s)],
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [13 col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME
-- per member.
----------------------------------------------------------------------------------------
with grp as (  -- one signature per loaded group (key, RECORD_SOURCE, LOAD_DATETIME)
    select PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME,
           listagg(to_varchar(IDENTIFICATION_TYPE_CODE) || ':' || to_varchar(HASHDIFF, 'HEX'), ',')
               within group (order by IDENTIFICATION_TYPE_CODE, HASHDIFF) as sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_IDENTIFICATION
     where RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW')
     group by PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME
),
seq as (
    select *, lag(sig) over (partition by PARTY_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_sig from grp
)
select 'MAXIMUS' as project, 'SAT_AUG_PARTY_IDENTIFICATION' as satellite,
       count(*) as versions, count_if(sig = prev_sig) as unchanged_reinserts,
       array_slice(array_agg(iff(sig = prev_sig, to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as examples,
       iff(unchanged_reinserts = 0, 'PASS', 'FAIL') as status
  from seq;



