       count_if(payload_sig = prev_payload_sig) as unchanged_payload_reinserts,
       array_slice(array_agg(iff(HASHDIFF = prev_hashdiff or payload_sig = prev_payload_sig, to_varchar(POLICY_HKEY, 'HEX'), null))
