-- 210. MAXIMUS — SAT_AUG_QUOTE_COVERAGE_SCHEDULE   [Implemented]
-- Multi-active: a version is the whole member set loaded at one LOAD_DATETIME; two
-- consecutive identical sets = an unchanged group was re-inserted. augmented satellite,
-- automate_dv.ma_sat; PK QUOTE_HKEY, child key COVERAGE_REFERENCE; 1 RECORD_SOURCE
-- group(s):
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_POLICY_PROPERTY_MULTI_SET_PROPERTY_INPUT_MULTI_SET_DETAIL_INPUT_PROPERTY_PIVOT_VW
-- [9 col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME
-- per member.
----------------------------------------------------------------------------------------
with grp as (  -- one signature per loaded group (key, RECORD_SOURCE, LOAD_DATETIME)
    select QUOTE_HKEY, RECORD_SOURCE, LOAD_DATETIME,
           listagg(to_varchar(COVERAGE_REFERENCE) || ':' || to_varchar(HASHDIFF, 'HEX'), ',')
               within group (order by COVERAGE_REFERENCE, HASHDIFF) as sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_QUOTE_COVERAGE_SCHEDULE
     where RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_POLICY_PROPERTY_MULTI_SET_PROPERTY_INPUT_MULTI_SET_DETAIL_INPUT_PROPERTY_PIVOT_VW')
     group by QUOTE_HKEY, RECORD_SOURCE, LOAD_DATETIME
),
seq as (
    select *, lag(sig) over (partition by QUOTE_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_sig from grp
)
select 'MAXIMUS' as project, 'SAT_AUG_QUOTE_COVERAGE_SCHEDULE' as satellite,
       count(*) as versions, count_if(sig = prev_sig) as unchanged_reinserts,
       array_slice(array_agg(iff(sig = prev_sig, to_varchar(QUOTE_HKEY, 'HEX'), null)) within group (order by QUOTE_HKEY), 0, 3) as examples,
       iff(unchanged_reinserts = 0, 'PASS', 'FAIL') as status
  from seq;



